import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

selu_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void selu_kernel(const float* x, float* out, int size, float alpha, float scale) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = x[idx];
        if (val >= 0.0f) {
            out[idx] = scale * val;
        } else {
            out[idx] = scale * (alpha * (expf(val) - 1.0f));
        }
    }
}

torch::Tensor selu_cuda(torch::Tensor x) {
    auto out = torch::zeros_like(x);
    int size = x.numel();
    float alpha = 1.6732632423543772f;
    float scale = 1.0507009873554804f;

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    selu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size, alpha, scale);
    return out;
}
"""

selu_cpp_source = "torch::Tensor selu_cuda(torch::Tensor x);"

selu_extension = load_inline(
    name="selu_extension",
    cpp_sources=selu_cpp_source,
    cuda_sources=selu_source,
    functions=["selu_cuda"],
    verbose=False,
    extra_cflags=[""],
    extra_ldflags=[""],
)

class ModelNew(nn.Module):
    """
    Simple model that performs a custom SELU activation via a CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        """
        Applies SELU activation to the input tensor using the custom CUDA kernel.
        """
        return selu_extension.selu_cuda(x)

